#!/usr/bin/env python3
"""
Session ID Bridge Tool
Maps TUI session UUIDs to message_index.json keys by matching display names
or examining export data.
"""

import json
import os
import sys
import argparse
from pathlib import Path
from typing import Dict, List, Optional, Tuple

class SessionBridge:
    def __init__(self, sessions_dir: str, index_path: str):
        self.sessions_dir = Path(sessions_dir)
        self.index_path = Path(index_path)
        self.sessions_data = {}
        self.message_index = {}

    def load_sessions(self) -> Dict:
        """Load all TUI session JSON files."""
        sessions = {}
        for session_file in self.sessions_dir.glob("*.json"):
            try:
                with open(session_file, 'r') as f:
                    data = json.load(f)
                    session_id = data.get('session_id')
                    if session_id:
                        sessions[session_id] = data
            except Exception as e:
                print(f"Warning: Could not load {session_file}: {e}", file=sys.stderr)
        self.sessions_data = sessions
        return sessions

    def load_message_index(self) -> Dict:
        """Load the message_index.json file."""
        try:
            with open(self.index_path, 'r') as f:
                self.message_index = json.load(f)
            return self.message_index
        except Exception as e:
            print(f"Error loading message_index: {e}", file=sys.stderr)
            return {}

    def find_by_display_name(self, session_uuid: str) -> Optional[str]:
        """Find message_index key by matching display_name."""
        if session_uuid not in self.sessions_data:
            return None

        session = self.sessions_data[session_uuid]
        display_name = session.get('display_name')

        if not display_name:
            return None

        # Search through message_index for matching metadata
        for key, value in self.message_index.items():
            if isinstance(value, dict):
                # Check if key itself matches display_name
                if key == display_name:
                    return key
                # Check metadata fields
                if value.get('display_name') == display_name:
                    return key
                if value.get('title') == display_name:
                    return key
                if value.get('name') == display_name:
                    return key

        return None

    def find_by_export_data(self, session_uuid: str) -> Optional[str]:
        """Find message_index key by examining conversation export data."""
        if session_uuid not in self.sessions_data:
            return None

        session = self.sessions_data[session_uuid]
        messages = session.get('messages', [])

        if not messages:
            return None

        # Extract first user message content or title
        first_user_msg = None
        for msg in messages:
            if msg.get('role') == 'user':
                first_user_msg = msg.get('content', '')
                break

        if not first_user_msg:
            return None

        # Search through message_index for matching conversation content
        for key, value in self.message_index.items():
            if isinstance(value, dict):
                # Check conversation starter
                if value.get('first_message') == first_user_msg[:100]:  # Compare first 100 chars
                    return key
                # Check messages array
                if 'messages' in value and isinstance(value['messages'], list):
                    for msg in value['messages'][:3]:  # Check first few messages
                        if msg.get('content') == first_user_msg[:100]:
                            return key

        return None

    def find_by_metadata_match(self, session_uuid: str) -> Optional[str]:
        """Find by matching metadata like timestamps, message counts."""
        if session_uuid not in self.sessions_data:
            return None

        session = self.sessions_data[session_uuid]
        session_msg_count = len(session.get('messages', []))
        session_created = session.get('created_at', '')

        if session_created:
            session_date = session_created[:10]  # YYYY-MM-DD

        for key, value in self.message_index.items():
            if isinstance(value, dict):
                # Match message count
                index_msg_count = len(value.get('messages', []))
                if index_msg_count == session_msg_count:
                    # Match timestamp
                    if value.get('created_at', '').startswith(session_date) if session_created else False:
                        return key

        return None

    def bridge_session(self, session_uuid: str, methods: List[str] = None) -> Dict[str, Optional[str]]:
        """
        Bridge a TUI session UUID to message_index key using specified methods.

        Args:
            session_uuid: The TUI session UUID
            methods: List of methods to try in order: 
                    ['display_name', 'export_data', 'metadata']
                    Default: all methods

        Returns:
            Dict with method used and found key
        """
        if methods is None:
            methods = ['display_name', 'export_data', 'metadata']

        self.load_sessions()
        self.load_message_index()

        if session_uuid not in self.sessions_data:
            return {'error': f'Session {session_uuid} not found', 'key': None}

        result = {'session_uuid': session_uuid, 'key': None, 'method': None}

        for method in methods:
            if method == 'display_name':
                key = self.find_by_display_name(session_uuid)
                if key:
                    result['key'] = key
                    result['method'] = 'display_name'
                    break
            elif method == 'export_data':
                key = self.find_by_export_data(session_uuid)
                if key:
                    result['key'] = key
                    result['method'] = 'export_data'
                    break
            elif method == 'metadata':
                key = self.find_by_metadata_match(session_uuid)
                if key:
                    result['key'] = key
                    result['method'] = 'metadata'
                    break

        return result

    def list_all_sessions(self) -> List[Tuple[str, str, Optional[str]]]:
        """List all sessions with their bridge status."""
        self.load_sessions()
        self.load_message_index()

        results = []
        for session_uuid, session_data in self.sessions_data.items():
            display_name = session_data.get('display_name', 'Unknown')
            msg_count = len(session_data.get('messages', []))

            # Try to find bridge
            bridge_result = self.bridge_session(session_uuid)
            index_key = bridge_result.get('key')

            results.append((session_uuid, display_name, msg_count, index_key))

        return results

    def create_mapping_report(self, output_file: str = None) -> Dict:
        """Generate a complete mapping report."""
        self.load_sessions()
        self.load_message_index()

        mapping = {}
        for session_uuid in self.sessions_data.keys():
            bridge_result = self.bridge_session(session_uuid)
            mapping[session_uuid] = {
                'message_index_key': bridge_result.get('key'),
                'method_used': bridge_result.get('method'),
                'display_name': self.sessions_data[session_uuid].get('display_name'),
                'message_count': len(self.sessions_data[session_uuid].get('messages', []))
            }

        if output_file:
            with open(output_file, 'w') as f:
                json.dump(mapping, f, indent=2)

        return mapping


def main():
    parser = argparse.ArgumentParser(
        description='Bridge TUI session UUIDs to message_index.json keys'
    )
    parser.add_argument('session_uuid', nargs='?', 
                       help='TUI session UUID to bridge')
    parser.add_argument('--list', action='store_true',
                       help='List all sessions with bridge status')
    parser.add_argument('--report', type=str, metavar='FILE',
                       help='Generate mapping report to FILE')
    parser.add_argument('--methods', nargs='+', 
                       choices=['display_name', 'export_data', 'metadata'],
                       default=['display_name', 'export_data', 'metadata'],
                       help='Methods to try for bridging')

    args = parser.parse_args()

    # Default paths
    sessions_dir = os.path.expanduser('~/cli-synthegration/conv_repo/sessions/')
    index_path = os.path.expanduser('~/cli-synthegration/conv_repo/message_index.json')

    bridge = SessionBridge(sessions_dir, index_path)

    if args.report:
        mapping = bridge.create_mapping_report(args.report)
        print(f"Mapping report saved to {args.report}")
        print(f"Total sessions: {len(mapping)}")
        bridged = sum(1 for v in mapping.values() if v['message_index_key'])
        print(f"Successfully bridged: {bridged}")
        return

    if args.list:
        results = bridge.list_all_sessions()
        print(f"{'Session UUID':<38} {'Display Name':<30} {'Msgs':<6} {'Bridged To':<20}")
        print("-" * 100)
        for uuid, name, count, key in results:
            key_display = key[:20] if key else 'NOT FOUND'
            print(f"{uuid:<38} {name[:30]:<30} {count:<6} {key_display:<20}")
        return

    if args.session_uuid:
        result = bridge.bridge_session(args.session_uuid, args.methods)
        if 'error' in result:
            print(f"Error: {result['error']}", file=sys.stderr)
            sys.exit(1)

        print(f"Session UUID: {result['session_uuid']}")
        print(f"Message Index Key: {result['key'] or 'NOT FOUND'}")
        print(f"Method used: {result['method'] or 'NONE'}")

        if result['key']:
            # Show session details
            session = bridge.sessions_data.get(result['session_uuid'])
            if session:
                print(f"Display name: {session.get('display_name', 'N/A')}")
                print(f"Message count: {len(session.get('messages', []))}")
        else:
            sys.exit(1)
    else:
        parser.print_help()


if __name__ == '__main__':
    main()
